// Writes `src/sin-table.ts`: the quarter-wave sine table behind `isin` and `icos`.
//
// Run once with `node --import tsx packages/content/scripts/gen-sin-table.ts` from the repo root,
// then `pnpm format`. The table is checked in, so the sim never calls `Math.sin` at runtime and
// every engine reads the same integers. `packages/content/test/fixed.test.ts` checks the table
// against this formula, so a hand edit to the generated file fails the tests.

import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/** Angle steps in a quarter turn (a full turn is 4096). */
const QUARTER = 1024;
/** The value of sine 1, as an integer: 2^14. */
const ONE = 16384;

export function sinTableEntry(i: number): number {
  return Math.round(Math.sin((i * Math.PI) / (2 * QUARTER)) * ONE);
}

const values: number[] = [];
for (let i = 0; i <= QUARTER; i++) values.push(sinTableEntry(i));

const out = `// Generated by packages/content/scripts/gen-sin-table.ts. Do not edit by hand.
//
// SIN_TABLE[i] = round(sin(i / 4096 turn) * 2^14) for i = 0..1024 (one quarter turn).

export const SIN_TABLE: readonly number[] = Object.freeze([
  ${values.join(", ")},
]);
`;

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(fileURLToPath(new URL("../src/sin-table.ts", import.meta.url)), out);
}
